import { useState } from 'react';
import type { FormEvent } from 'react';
import { JxStepper, JxInputField, JxButton } from '@jinx-ui/react';

interface RegistrationData {
  fullName: string;
  email: string;
  street: string;
  city: string;
  postalCode: string;
}

interface RegistrationWizardProps {
  onSubmit: (data: RegistrationData) => void;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>({
    fullName: '',
    email: '',
    street: '',
    city: '',
    postalCode: '',
  });

  const update = (field: keyof RegistrationData) => (event: React.ChangeEvent<HTMLInputElement>) => {
    setData((prev) => ({ ...prev, [field]: event.target.value }));
  };

  const isLastStep = step === steps.length - 1;

  const canGoNext =
    step === 0
      ? data.fullName.trim().length > 0 && data.email.includes('@')
      : step === 1
        ? data.street.trim().length > 0 && data.city.trim().length > 0
        : true;

  const handleNext = () => {
    if (isLastStep) {
      onSubmit(data);
      return;
    }
    setStep((current) => Math.min(current + 1, steps.length - 1));
  };

  const handleBack = () => {
    setStep((current) => Math.max(current - 1, 0));
  };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    handleNext();
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-lg)' }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r)' }}>
          <JxInputField
            label="Полное имя"
            required
            value={data.fullName}
            onChange={update('fullName')}
            autoFocus
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={data.email}
            onChange={update('email')}
            errorText={
              data.email.length > 0 && !data.email.includes('@')
                ? 'Укажите адрес с символом @'
                : undefined
            }
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r)' }}>
          <JxInputField
            label="Улица и дом"
            required
            value={data.street}
            onChange={update('street')}
            autoFocus
          />
          <JxInputField
            label="Город"
            required
            value={data.city}
            onChange={update('city')}
          />
          <JxInputField
            label="Почтовый индекс"
            value={data.postalCode}
            onChange={update('postalCode')}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-r)' }}>
            <span style={{ color: 'var(--jx-text-2)' }}>Имя</span>
            <span style={{ color: 'var(--jx-text)' }}>{data.fullName || '—'}</span>
          </div>
          <div style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-r)' }}>
            <span style={{ color: 'var(--jx-text-2)' }}>Почта</span>
            <span style={{ color: 'var(--jx-text)' }}>{data.email || '—'}</span>
          </div>
          <div style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-r)' }}>
            <span style={{ color: 'var(--jx-text-2)' }}>Адрес</span>
            <span style={{ color: 'var(--jx-text)' }}>
              {[data.street, data.city, data.postalCode].filter(Boolean).join(', ') || '—'}
            </span>
          </div>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-r)' }}>
        <JxButton type="button" variant="ghost" disabled={step === 0} onClick={handleBack}>
          Назад
        </JxButton>
        <JxButton type="submit" variant="primary" disabled={!canGoNext}>
          {isLastStep ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

